def get_BR_i(task_i, all_phasings):
    min_R = infinity
    for phi in all_phasings:
        for job in task_i.get_jobs(phi):
            min_R = min(min_R, job.R_i_k)
    return min_R

def is_schedulable(task_set):
    for task_i in task_set:
        if task_i.BR < task_i.BD or task_i.WR > task_i.WD:
            return False
    return True

def calculate_best_case_utilization(task_set):
    BU_T = 0
    for task_i in task_set:
        BU_T += task_i.BC / task_i.T
    return BU_T

def get_non_preemptive_BR(task_i, task_set):
    if task_i.theta == pi_max:
        bu_t = calculate_best_case_utilization(task_set)
        if bu_t <= 1:
            return task_i.BC
    return None
